const fs = require('fs');
const path = require('path');

const inputPath = path.join(__dirname, 'config.json');
const outputPath = path.join(__dirname, 'config.out.json');

const raw = fs.readFileSync(inputPath, 'utf8');
const config = JSON.parse(raw);

if (config.port === undefined) config.port = 3000;
if (config.host === undefined) config.host = '127.0.0.1';

fs.writeFileSync(outputPath, JSON.stringify(config, null, 2));
console.log('Wrote', outputPath, JSON.stringify(config));

